import{_ as a,o as r,c as i,a5 as t}from"./chunks/framework.UjrY2eRK.js";const u=JSON.parse('{"title":"Gate administration releases with real OIDC providers","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/adr/0027-gate-administration-releases-with-real-oidc-providers.md","filePath":"architecture/adr/0027-gate-administration-releases-with-real-oidc-providers.md","lastUpdated":1788245587000}'),s={name:"architecture/adr/0027-gate-administration-releases-with-real-oidc-providers.md"};function o(n,e,d,c,l,p){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="gate-administration-releases-with-real-oidc-providers" tabindex="-1">Gate administration releases with real OIDC providers <a class="header-anchor" href="#gate-administration-releases-with-real-oidc-providers" aria-label="Permalink to &quot;Gate administration releases with real OIDC providers&quot;">​</a></h1><p>Administration-capable releases must pass three layers of evidence: the fast deterministic <code>oidc-provider</code> protocol suite, an assembled-image smoke and isolation suite, and browser login tests against pinned disposable Pocket ID and Authentik services. The real-provider layer covers allowed and denied users, exact redirect and logout URIs, Operator Session creation, deep-link preservation, provider-outage isolation, and a directly uploaded browser screenshot.</p><p>Pull requests run the deterministic suite and Pocket ID compatibility. Scheduled and release-capable runs also require Authentik compatibility. Provider services and credentials are created only for a run; credentials are generated, masked, written with restrictive permissions, excluded from artifacts, and destroyed with the disposable services. FCM remains mocked because this gate verifies the operator boundary rather than mobile delivery credentials.</p><p>The production image is built once for each gate and must be the same artifact exercised by the smoke, provider, and size checks. It contains only the minified Bun bundle, compiled browser assets, and canonical gateway and administration migrations; it excludes sources, source maps, tests, package-manager state, and <code>node_modules</code>. Runtime validation requires numeric UID and GID 1000, a read-only root filesystem, and a writable <code>/data</code> volume.</p><p>An administration benchmark alternates disabled and enabled runs against the same delivery endpoint, requires zero notification errors while metrics persistence fails and backup or cleanup work runs, and rejects a sustained median p95 regression above five percent. An initial majority-screen regression must repeat above the threshold in every paired round of a separate five-round confirmation series whose starting order is reversed; this confirmation is the first one-sided sign-test outcome below five percent under random order noise. A noisy round or series does not fail the gate.</p>',5)])])}const h=a(s,[["render",o]]);export{u as __pageData,h as default};
